//! `tuxrgb-helper` – the only part of TuxRGB that ever runs as root.
//!
//! It is started by the GUI through `pkexec` (Polkit asks for the
//! administrator password) and accepts exactly four fixed verbs:
//!
//! * `install` – reads udev rules generated by the bundled OpenRGB on stdin
//!   and validates them line by line. Without distribution rules it writes
//!   `/etc/udev/rules.d/60-openrgb.rules`; when the distribution already
//!   ships `/usr/lib/udev/rules.d/60-openrgb.rules` (Bazzite…) it only adds
//!   the rules that file lacks, in `61-tuxrgb-openrgb-extra.rules`, so the
//!   two never conflict. Then it configures `i2c-dev` + the chipset SMBus
//!   driver in `/etc/modules-load.d/tuxrgb-i2c.conf`, loads the modules and
//!   reloads udev.
//! * `enable-smbus` – fixes the SMBus being refused by the firmware (RAM and
//!   some motherboard lighting missing), and only what is actually broken:
//!   when the chipset's SMBus driver is not bound it adds the kernel
//!   parameter `acpi_enforce_resources=lax` with the method of the running
//!   system (rpm-ostree, grubby, kernelstub, GRUB, systemd-boot, rEFInd –
//!   see [`bootloader`]); when the DDR5 `spd5118` sensor driver sits on the
//!   memory bus it keeps it off. If the SMBus already works, nothing is
//!   touched. Needs a reboot when something changed.
//! * `reset`   – removes exactly what `install` / `enable-smbus` created
//!   (tracked in `/var/lib/tuxrgb/installed.list`), restores any
//!   pre-existing file and reloads udev.
//! * `status`  – prints the current state (no root needed).
//!
//! No path, command or option is ever taken from the caller, the environment
//! is ignored and every external tool is called by absolute path.

mod bootloader;
mod rules;
mod system;

use std::io::Read;
use std::path::Path;
use std::process::ExitCode;

pub const RULES_PATH: &str = "/etc/udev/rules.d/60-openrgb.rules";
/// Complement of the distribution's rules (only devices it does not know).
pub const EXTRA_RULES_PATH: &str = "/etc/udev/rules.d/61-tuxrgb-openrgb-extra.rules";
pub const VENDOR_RULES: &[&str] = &[
    "/usr/lib/udev/rules.d/60-openrgb.rules",
    "/lib/udev/rules.d/60-openrgb.rules",
];
pub const SPD_BLACKLIST_PATH: &str = "/etc/modprobe.d/tuxrgb-spd5118.conf";
pub const SMBUS_KARG: &str = "acpi_enforce_resources=lax";
pub const MODULES_PATH: &str = "/etc/modules-load.d/tuxrgb-i2c.conf";
pub const STATE_DIR: &str = "/var/lib/tuxrgb";
pub const MANIFEST_PATH: &str = "/var/lib/tuxrgb/installed.list";
pub const BACKUP_PATH: &str = "/var/lib/tuxrgb/backup-60-openrgb.rules";
/// Copies of boot configuration files taken before the first edit.
pub const BOOT_BACKUP_DIR: &str = "/var/lib/tuxrgb/boot-backup";
pub const HEADER: &str = "# Installed by TuxRGB (io.github.tuxrgb.TuxRGB) – generated by the bundled OpenRGB.\n# Remove with: TuxRGB → Paramètres → Réinitialiser les permissions / Accès matériel\n";

/// Exit codes understood by the GUI.
mod code {
    pub const OK: u8 = 0;
    pub const USAGE: u8 = 2;
    pub const NOT_ROOT: u8 = 3;
    pub const INVALID_RULES: u8 = 4;
    pub const IO: u8 = 5;
    /// The bootloader cannot be changed automatically: the message says how.
    pub const MANUAL: u8 = 6;
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let verb = match args.as_slice() {
        [v] => v.as_str(),
        _ => return usage(),
    };
    let result = match verb {
        "status" => {
            print!("{}", system::status_report());
            Ok(())
        }
        "install" | "reset" | "enable-smbus" => {
            if !system::is_root() {
                eprintln!("tuxrgb-helper: must be run as root (through pkexec)");
                return ExitCode::from(code::NOT_ROOT);
            }
            system::harden_process();
            // Audit trail: who asked (pkexec sets it), read before the
            // environment is wiped.
            let caller: String = std::env::var("PKEXEC_UID")
                .unwrap_or_default()
                .chars()
                .filter(char::is_ascii_digit)
                .take(10)
                .collect();
            system::sanitize_environment();
            if !caller.is_empty() {
                println!("STEP requested-by-uid {caller}");
            }
            match verb {
                "install" => install(),
                "enable-smbus" => enable_smbus(),
                _ => reset(),
            }
        }
        "--version" => {
            println!("tuxrgb-helper {}", env!("CARGO_PKG_VERSION"));
            Ok(())
        }
        _ => return usage(),
    };
    match result {
        Ok(()) => {
            println!("RESULT ok");
            ExitCode::from(code::OK)
        }
        Err((c, msg)) => {
            eprintln!("tuxrgb-helper: {msg}");
            println!("RESULT error {msg}");
            ExitCode::from(c)
        }
    }
}

fn usage() -> ExitCode {
    eprintln!("usage: tuxrgb-helper install|enable-smbus|reset|status");
    ExitCode::from(code::USAGE)
}

type HelperResult = Result<(), (u8, String)>;

fn io_err(context: &str) -> impl Fn(std::io::Error) -> (u8, String) + '_ {
    move |e| (code::IO, format!("{context}: {e}"))
}

fn install() -> HelperResult {
    // 1. Rules from stdin (bounded), validated before anything is touched.
    let mut input = String::new();
    std::io::stdin()
        .take(rules::MAX_RULES_BYTES as u64 + 1)
        .read_to_string(&mut input)
        .map_err(io_err("lecture de l'entrée standard"))?;
    if input.len() > rules::MAX_RULES_BYTES {
        return Err((code::INVALID_RULES, "règles udev trop volumineuses".into()));
    }
    // Never any universal permission: OpenRGB's few `chmod a+w` rules (ASUS /
    // faustus laptop keyboards) are removed before validation, which then
    // refuses anything that could still grant rights to every user.
    let (input, removed) = rules::sanitize(&input);
    for r in &removed {
        println!("STEP removed-world-writable {r}");
    }
    let validated = rules::validate(&input).map_err(|e| (code::INVALID_RULES, e))?;
    println!("STEP rules-validated {} règles", validated.rule_count);

    system::ensure_dir(STATE_DIR, 0o755).map_err(io_err(STATE_DIR))?;
    let mut manifest = system::Manifest::load(MANIFEST_PATH);
    system::ensure_dir("/etc/udev/rules.d", 0o755).map_err(io_err("/etc/udev/rules.d"))?;

    let vendor = VENDOR_RULES.iter().copied().find(|p| Path::new(p).exists());
    if let Some(vendor) = vendor {
        // 2a. The distribution ships OpenRGB rules: a second
        //     60-openrgb.rules in /etc would hide it (and OpenRGB warns about
        //     "multiple udev rules"). Remove ours, add only what is missing.
        if Path::new(RULES_PATH).exists() {
            let ours = manifest.owns(RULES_PATH)
                || std::fs::read_to_string(RULES_PATH)
                    .map(|s| s.starts_with("# Installed by TuxRGB"))
                    .unwrap_or(false);
            if !ours && manifest.backup.is_none() {
                // Hand-made copy: kept aside, « Réinitialiser » puts it back.
                std::fs::copy(RULES_PATH, BACKUP_PATH)
                    .map_err(io_err("sauvegarde des règles existantes"))?;
                manifest.backup = Some(BACKUP_PATH.into());
                println!("STEP backup {RULES_PATH} -> {BACKUP_PATH}");
            }
            std::fs::remove_file(RULES_PATH).map_err(io_err(RULES_PATH))?;
            println!("STEP removed-duplicate {RULES_PATH}");
        }
        manifest.remove(RULES_PATH);
        let vendor_text = std::fs::read_to_string(vendor).map_err(io_err(vendor))?;
        let (extra, n) = rules::complement(&validated.text, &vendor_text);
        // The distribution's file may grant world write access itself
        // (`chmod a+w`): take it back right after, with the same match.
        let (revoke, revoked) = rules::neutralize(&vendor_text);
        println!("STEP vendor-rules {vendor}");
        if revoked > 0 {
            println!("STEP vendor-world-writable-revoked {revoked}");
        }
        if n + revoked > 0 {
            let mut content = format!(
                "{HEADER}{}\n# Complement of {vendor}: devices it does not list yet.\n\n{extra}",
                rules::RULES_FORMAT
            );
            if revoked > 0 {
                content.push_str(&format!(
                    "\n# Write access for everyone granted by {vendor}, taken back:\n{revoke}"
                ));
            }
            // Same strict checks as the input before writing as root.
            rules::validate(&content).map_err(|e| (code::INVALID_RULES, e))?;
            system::write_atomic(EXTRA_RULES_PATH, content.as_bytes(), 0o644)
                .map_err(io_err(EXTRA_RULES_PATH))?;
            manifest.add(EXTRA_RULES_PATH);
            println!(
                "STEP rules-written {EXTRA_RULES_PATH} ({n} règles complémentaires, {revoked} droits retirés)"
            );
        } else {
            if let Ok(()) = std::fs::remove_file(EXTRA_RULES_PATH) {
                println!("STEP removed {EXTRA_RULES_PATH}")
            }
            manifest.remove(EXTRA_RULES_PATH);
            println!("STEP rules-complete aucune règle à ajouter");
        }
    } else {
        // 2b. No distribution rules: install the full set.
        //     Keep a copy of a foreign rules file (e.g. installed by hand).
        if Path::new(RULES_PATH).exists() && !manifest.owns(RULES_PATH) {
            let current = std::fs::read_to_string(RULES_PATH).unwrap_or_default();
            if !current.starts_with("# Installed by TuxRGB") {
                std::fs::copy(RULES_PATH, BACKUP_PATH)
                    .map_err(io_err("sauvegarde des règles existantes"))?;
                manifest.backup = Some(BACKUP_PATH.into());
                println!("STEP backup {RULES_PATH} -> {BACKUP_PATH}");
            }
        }
        let content = format!("{HEADER}{}\n\n{}", rules::RULES_FORMAT, validated.text);
        system::write_atomic(RULES_PATH, content.as_bytes(), 0o644).map_err(io_err(RULES_PATH))?;
        manifest.add(RULES_PATH);
        println!("STEP rules-written {RULES_PATH}");
        let _ = std::fs::remove_file(EXTRA_RULES_PATH);
        manifest.remove(EXTRA_RULES_PATH);
    }

    // 4. I2C / SMBus modules (motherboard and RAM lighting).
    let modules = system::smbus_modules();
    system::ensure_dir("/etc/modules-load.d", 0o755).map_err(io_err("/etc/modules-load.d"))?;
    let mut conf =
        String::from("# TuxRGB – I2C/SMBus access for motherboard and RAM RGB (OpenRGB)\n");
    for m in &modules {
        conf.push_str(m);
        conf.push('\n');
    }
    system::write_atomic(MODULES_PATH, conf.as_bytes(), 0o644).map_err(io_err(MODULES_PATH))?;
    manifest.add(MODULES_PATH);
    println!("STEP modules-config {}", modules.join(","));
    for m in &modules {
        match system::run("modprobe", &[m]) {
            Ok(()) => println!("STEP modprobe {m} ok"),
            Err(e) => println!("STEP modprobe {m} skipped ({e})"),
        }
    }
    system::restorecon(&[RULES_PATH, EXTRA_RULES_PATH, MODULES_PATH]);

    manifest
        .save(MANIFEST_PATH)
        .map_err(io_err(MANIFEST_PATH))?;

    // 5. Apply.
    reload_udev();
    Ok(())
}

/// SMBus refused by the firmware (typical on Gigabyte AM5/Intel boards):
/// the chipset driver cannot bind, so RAM and some motherboard lighting are
/// invisible. Same fix as OpenRGB's documentation, applied only if needed.
fn enable_smbus() -> HelperResult {
    system::ensure_dir(STATE_DIR, 0o755).map_err(io_err(STATE_DIR))?;
    let mut manifest = system::Manifest::load(MANIFEST_PATH);
    let mut changed = false;

    // 0. What is actually broken?
    let mut controllers = system::smbus_controllers();
    for c in &controllers {
        println!(
            "STEP smbus-controller {} {} {}",
            c.address,
            c.vendor,
            c.driver.as_deref().unwrap_or("none")
        );
    }
    if controllers.iter().any(|c| c.driver.is_none()) {
        // The module may simply not be loaded yet.
        for m in system::smbus_modules().iter().skip(1) {
            let _ = system::run("modprobe", &[m]);
        }
        controllers = system::smbus_controllers();
    }
    let unbound = controllers.iter().any(|c| c.driver.is_none());
    let spd = system::spd5118_in_use();
    if !unbound && !spd {
        // « Ne touche à rien si les accès SMBus/I2C sont déjà fonctionnels ».
        println!("STEP smbus-already-functional");
        return Ok(());
    }

    // 1. Kernel parameter, at the next boot. The value is a compile-time
    //    constant, re-checked against the allowlist and a strict character
    //    set before it reaches any tool or file (no shell is ever involved:
    //    arguments are passed as an argv array).
    if unbound {
        let karg = system::validated_karg(SMBUS_KARG).map_err(|e| (code::USAGE, e))?;
        let cmdline = std::fs::read_to_string("/proc/cmdline").unwrap_or_default();
        if cmdline.split_whitespace().any(|a| a == karg) {
            // Already booted with it: the conflict is elsewhere (BIOS).
            println!("STEP karg-present {karg}");
        } else {
            let method = bootloader::detect(system::has_tool);
            println!("STEP karg-tool {}", method.name());
            add_karg(&method, karg, &mut manifest)?;
            manifest.add_karg(karg);
            manifest.karg_method = Some(method.name().into());
            changed = true;
            println!("STEP karg-added {karg}");
        }
    }

    // 2. DDR5: the spd5118 temperature driver sits on the memory SPD hubs.
    if spd {
        system::ensure_dir("/etc/modprobe.d", 0o755).map_err(io_err("/etc/modprobe.d"))?;
        let conf = "# TuxRGB – keep the DDR5 SPD sensor driver off the memory bus so OpenRGB\n\
                    # can drive the RAM lighting (removed by « Réinitialiser les permissions »).\n\
                    blacklist spd5118\n";
        system::write_atomic(SPD_BLACKLIST_PATH, conf.as_bytes(), 0o644)
            .map_err(io_err(SPD_BLACKLIST_PATH))?;
        system::restorecon(&[SPD_BLACKLIST_PATH]);
        manifest.add(SPD_BLACKLIST_PATH);
        changed = true;
        println!("STEP spd5118-blacklisted {SPD_BLACKLIST_PATH}");
    }
    manifest
        .save(MANIFEST_PATH)
        .map_err(io_err(MANIFEST_PATH))?;
    if changed {
        println!("STEP reboot-required");
    }
    Ok(())
}

/// Copy of a boot file before its first edit (kept for « Réinitialiser »).
fn backup_boot_file(path: &str) -> HelperResult {
    system::ensure_dir(BOOT_BACKUP_DIR, 0o700).map_err(io_err(BOOT_BACKUP_DIR))?;
    let name = path.trim_start_matches('/').replace('/', "_");
    let dest = format!("{BOOT_BACKUP_DIR}/{name}");
    if !Path::new(&dest).exists() {
        std::fs::copy(path, &dest).map_err(io_err("sauvegarde"))?;
        println!("STEP backup {path} -> {dest}");
    }
    Ok(())
}

/// Edits one boot file with `edit`, atomically, after a backup.
fn edit_boot_file(
    path: &str,
    edit: impl Fn(&str, &str) -> Option<String>,
    karg: &str,
    manifest: &mut system::Manifest,
) -> Result<bool, (u8, String)> {
    if !bootloader::editable_path(path) {
        return Err((code::USAGE, format!("{path} : chemin refusé")));
    }
    let text = std::fs::read_to_string(path).map_err(io_err(path))?;
    let Some(new) = edit(&text, karg) else {
        return Ok(false);
    };
    backup_boot_file(path)?;
    let write = if path.starts_with("/boot") || path.starts_with("/efi") {
        system::write_atomic_boot
    } else {
        system::write_atomic
    };
    write(path, new.as_bytes(), 0o644).map_err(io_err(path))?;
    system::restorecon(&[path]);
    manifest.add_karg_file(path);
    println!("STEP karg-file {path}");
    Ok(true)
}

fn add_karg(
    method: &bootloader::Method,
    karg: &str,
    manifest: &mut system::Manifest,
) -> HelperResult {
    use bootloader::Method;
    let fail = |e: String| (code::IO, format!("paramètre noyau : {e}"));
    match method {
        Method::RpmOstree => {
            let append = format!("--append-if-missing={karg}");
            system::run("rpm-ostree", &["kargs", &append]).map_err(fail)
        }
        Method::Grubby => {
            let args = format!("--args={karg}");
            system::run("grubby", &["--update-kernel=ALL", &args]).map_err(fail)
        }
        Method::Kernelstub => system::run("kernelstub", &["--add-options", karg]).map_err(fail),
        Method::Grub { regen } => {
            if !edit_boot_file(
                bootloader::GRUB_DEFAULT,
                bootloader::grub_add,
                karg,
                manifest,
            )? {
                println!("STEP karg-already-configured {}", bootloader::GRUB_DEFAULT);
            }
            let (tool, args) = regen.split_first().ok_or_else(|| fail("grub".into()))?;
            system::run(tool, args).map_err(fail)
        }
        Method::SystemdBoot { entries } => {
            let mut any = false;
            for e in entries {
                any |= edit_boot_file(e, bootloader::entry_add, karg, manifest)?;
            }
            // Future kernels (kernel-install, UKI, sdbootutil).
            if Path::new(bootloader::KERNEL_CMDLINE).is_file() {
                any |= edit_boot_file(
                    bootloader::KERNEL_CMDLINE,
                    bootloader::cmdline_add,
                    karg,
                    manifest,
                )?;
            }
            if !any {
                println!("STEP karg-already-configured systemd-boot");
            }
            Ok(())
        }
        Method::Refind => edit_boot_file(
            bootloader::REFIND_CONF,
            bootloader::refind_add,
            karg,
            manifest,
        )
        .map(|_| ()),
        Method::Manual(how) => Err((code::MANUAL, how.clone())),
    }
}

fn reset() -> HelperResult {
    let manifest = system::Manifest::load(MANIFEST_PATH);
    for karg in manifest.kargs() {
        // The manifest lives in root-only /var/lib/tuxrgb, but is still
        // treated as untrusted input: only the allowlisted argument.
        let Ok(karg) = system::validated_karg(karg) else {
            println!("STEP ignored-unknown-karg");
            continue;
        };
        // TuxRGB ≤ 1.3 did not record the method: rpm-ostree or grubby.
        let method = manifest.karg_method.clone().unwrap_or_else(|| {
            if Path::new("/run/ostree-booted").exists() {
                "rpm-ostree".into()
            } else {
                "grubby".into()
            }
        });
        let r = match method.as_str() {
            "rpm-ostree" => {
                let delete = format!("--delete-if-present={karg}");
                system::run("rpm-ostree", &["kargs", &delete])
            }
            "grubby" => {
                let args = format!("--remove-args={karg}");
                system::run("grubby", &["--update-kernel=ALL", &args])
            }
            "kernelstub" => system::run("kernelstub", &["--delete-options", karg]),
            "grub" | "systemd-boot" | "refind" => {
                let mut result = Ok(());
                for path in manifest.karg_files() {
                    if !bootloader::editable_path(path) {
                        println!("STEP ignored-unknown-entry {path}");
                        continue;
                    }
                    let edit: fn(&str, &str) -> Option<String> = match path {
                        bootloader::GRUB_DEFAULT => bootloader::grub_remove,
                        bootloader::KERNEL_CMDLINE => bootloader::cmdline_remove,
                        bootloader::REFIND_CONF => bootloader::refind_remove,
                        _ => bootloader::entry_remove,
                    };
                    let Ok(text) = std::fs::read_to_string(path) else {
                        continue;
                    };
                    if let Some(new) = edit(&text, karg) {
                        let write = if path.starts_with("/boot") || path.starts_with("/efi") {
                            system::write_atomic_boot
                        } else {
                            system::write_atomic
                        };
                        if let Err(e) = write(path, new.as_bytes(), 0o644) {
                            result = Err(e.to_string());
                        } else {
                            system::restorecon(&[path]);
                            println!("STEP karg-file-restored {path}");
                        }
                    }
                }
                if method == "grub"
                    && let bootloader::Method::Grub { regen } = bootloader::detect(system::has_tool)
                    && let Some((tool, args)) = regen.split_first()
                    && let Err(e) = system::run(tool, args)
                {
                    result = Err(e);
                }
                result
            }
            _ => Err("méthode inconnue".into()),
        };
        match r {
            Ok(()) => println!("STEP karg-removed {karg}"),
            Err(e) => println!("STEP karg-remove-failed {karg} ({e})"),
        }
    }
    for path in manifest.files() {
        // Only ever delete the files this helper can create.
        if ![
            RULES_PATH,
            EXTRA_RULES_PATH,
            MODULES_PATH,
            SPD_BLACKLIST_PATH,
        ]
        .contains(&path)
        {
            println!("STEP ignored-unknown-entry {path}");
            continue;
        }
        match std::fs::remove_file(path) {
            Ok(()) => println!("STEP removed {path}"),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err((code::IO, format!("{path}: {e}"))),
        }
    }
    if let Some(backup) = manifest.backup.as_deref()
        && backup == BACKUP_PATH
        && Path::new(BACKUP_PATH).exists()
    {
        std::fs::copy(BACKUP_PATH, RULES_PATH).map_err(io_err("restauration des règles"))?;
        let _ = std::fs::remove_file(BACKUP_PATH);
        system::restorecon(&[RULES_PATH]);
        println!("STEP restored {RULES_PATH}");
    }
    match std::fs::remove_file(MANIFEST_PATH) {
        Ok(()) | Err(_) => {}
    }
    reload_udev();
    Ok(())
}

fn reload_udev() {
    for args in [
        &["control", "--reload-rules"][..],
        &["trigger", "--action=change"][..],
        &["settle", "--timeout=10"][..],
    ] {
        match system::run("udevadm", args) {
            Ok(()) => println!("STEP udevadm {} ok", args[0]),
            Err(e) => println!("STEP udevadm {} failed ({e})", args[0]),
        }
    }
}
